import java.util.*;import java.time.LocalDate;import java.time.format.DateTimeFormatter;import java.math.BigDecimal;import java.math.RoundingMode;import java.util.stream.Collectors;class Solution {    private static class Trip {        int id;        int client_id;        int driver_id;        String status;        String request_at;        public Trip(int id, int client_id, int driver_id, int city_id, String status, String request_at) {            this.id = id;            this.client_id = client_id;            this.driver_id = driver_id;            this.status = status;            this.request_at = request_at;        }    }    private static class User {        int users_id;        String banned;        public User(int users_id, String banned, String role) {            this.users_id = users_id;            this.banned = banned;        }    }    private List<Trip> parseTrips(List<List<String>> tripsData) {        List<Trip> trips = new ArrayList<>();        for (List<String> row : tripsData) {            trips.add(new Trip(                Integer.parseInt(row.get(0)),                Integer.parseInt(row.get(1)),                Integer.parseInt(row.get(2)),                Integer.parseInt(row.get(3)),                row.get(4),                row.get(5)            ));        }        return trips;    }    private List<User> parseUsers(List<List<String>> usersData) {        List<User> users = new ArrayList<>();        for (List<String> row : usersData) {            users.add(new User(                Integer.parseInt(row.get(0)),                row.get(1),                row.get(2)            ));        }        return users;    }    public List<List<String>> getCancellationRate(List<List<String>> tripsData, List<List<String>> usersData) {        List<Trip> trips = parseTrips(tripsData);        List<User> users = parseUsers(usersData);        Map<Integer, String> userBannedStatus = users.stream()            .collect(Collectors.toMap(user -> user.users_id, user -> user.banned));        LocalDate startDate = LocalDate.parse("2013-10-01");        LocalDate endDate = LocalDate.parse("2013-10-03");        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");        List<Trip> eligibleTrips = trips.stream()            .filter(trip -> {                LocalDate requestDate = LocalDate.parse(trip.request_at, formatter);                return !requestDate.isBefore(startDate) && !requestDate.isAfter(endDate);            })            .filter(trip -> {                String clientBanned = userBannedStatus.getOrDefault(trip.client_id, "Yes");                String driverBanned = userBannedStatus.getOrDefault(trip.driver_id, "Yes");                return "No".equals(clientBanned) && "No".equals(driverBanned);            })            .collect(Collectors.toList());        Map<String, List<Trip>> tripsByDate = eligibleTrips.stream()            .collect(Collectors.groupingBy(trip -> trip.request_at));        List<List<String>> result = new ArrayList<>();        for (Map.Entry<String, List<Trip>> entry : tripsByDate.entrySet()) {            String day = entry.getKey();            List<Trip> dailyTrips = entry.getValue();            int totalRequests = dailyTrips.size();            long cancelledRequests = dailyTrips.stream()                .filter(trip -> "cancelled_by_driver".equals(trip.status) || "cancelled_by_client".equals(trip.status))                .count();            double cancellationRate = 0.0;            if (totalRequests > 0) {                cancellationRate = (double) cancelledRequests / totalRequests;            }            BigDecimal bd = new BigDecimal(cancellationRate).setScale(2, RoundingMode.HALF_UP);            result.add(Arrays.asList(day, bd.toPlainString()));        }        result.sort(Comparator.comparing(row -> row.get(0)));        return result;    }}